class Solution:
    def superEggDrop(self, A: int, B: int) -> int:
        # f[k] = most floors that k eggs can settle in the current number of moves.
        f = [0] * (A + 1)
        moves = 0
        while f[A] < B:
            moves += 1
            for k in range(A, 0, -1):
                f[k] = f[k] + f[k - 1] + 1
        return moves

