class Solution {
public:
    int superEggDrop(int A, int B) {
        vector<long long> f(A + 1, 0); int moves = 0;
        while (f[A] < B) { moves++; for (int k = A; k > 0; k--) f[k] = f[k] + f[k - 1] + 1; }
        return moves;
    }
};

